// path: adapters/mongo/role_alias_store.go
package mongo

import (
	"context"

	"go.mongodb.org/mongo-driver/v2/mongo"

	"github.com/tekroo-ai/teams/organization"
)

type RoleAliasStore struct {
	collection *mongo.Collection
}

func NewRoleAliasStore(db *mongo.Database) *RoleAliasStore { ... }

func (s *RoleAliasStore) Load(ctx context.Context, name string) (organization.RoleAlias, bool, error) { ... }
func (s *RoleAliasStore) Save(ctx context.Context, alias organization.RoleAlias) error { ... }
func (s *RoleAliasStore) Delete(ctx context.Context, name string) error { ... }
func (s *RoleAliasStore) List(ctx context.Context) ([]organization.RoleAlias, error) { ... }
```
The collection name is "role_aliases". Save uses a single-document updateOne with upsert:true and a $inc on revision to prevent lost updates. An ensureIndexes call creates a unique index on Name. Load and Delete return organization.ErrRoleAliasNotFound when no document matches.

